INSERT INTO permissions(code) VALUES ('INVENTORY_COST_READ'),('INVENTORY_RESERVE'),('INVENTORY_TRANSFER'),('INVENTORY_ADJUST'),('ESTIMATE_READ'),('INVOICE_WRITE'),('PAYMENT_RECORD'),('PAYMENT_RECONCILE'),('PAYMENT_REFUND');
INSERT INTO role_permissions(role,permission) SELECT r.code,p.code FROM roles r CROSS JOIN permissions p WHERE r.code IN ('BRAND_OWNER','REGIONAL_MANAGER','BRANCH_MANAGER') AND p.code IN ('INVENTORY_COST_READ','INVENTORY_RESERVE','INVENTORY_TRANSFER','INVENTORY_ADJUST','ESTIMATE_READ','INVOICE_WRITE','PAYMENT_RECORD','PAYMENT_RECONCILE','PAYMENT_REFUND');
